using StockSyncAI.Api.Services;namespace StockSyncAI.Api.Endpoints;
public static class InvoicePostingEndpoints
{public static IEndpointRouteBuilder MapInvoicePostingEndpoints(this IEndpointRouteBuilder e){e.MapGet("/api/invoices/{id:guid}/posting",Get);e.MapPost("/api/invoices/{id:guid}/posting/prepare",Prepare);e.MapPost("/api/invoices/{id:guid}/posting/{postingId:guid}/execute",Post);return e;}private static async Task<IResult> Get(Guid id,IInvoicePostingService s,CancellationToken t)=>await Run(()=>s.GetStatusAsync(id,t));private static async Task<IResult> Prepare(Guid id,IInvoicePostingService s,CancellationToken t)=>await Run(()=>s.PrepareAsync(id,t));private static async Task<IResult> Post(Guid id,Guid postingId,PostRequest? r,IInvoicePostingService s,CancellationToken t)=>r is null?Results.BadRequest(new{error="Posting confirmation is required."}):await Run(()=>s.PostAsync(id,postingId,r.Confirmation,t));private static async Task<IResult> Run(Func<Task<Models.PostingStatusResult>> action){try{return Results.Ok(await action());}catch(InvoiceNotFoundException){return Results.NotFound(new{error="The requested invoice was not found."});}catch(PostingValidationException x){return Results.UnprocessableEntity(new{error=x.Message});}catch(PostingConflictException x){return Results.Conflict(new{error=x.Message});}catch(PosConfirmedRollbackException x){return Results.Json(new{error=x.Message},statusCode:503);}catch(PosOutcomeUnknownException x){return Results.Json(new{error=x.Message},statusCode:409);}catch(OperationCanceledException){throw;}catch{return Results.Json(new{error="The posting operation could not be completed safely."},statusCode:500);}}public sealed record PostRequest(string Confirmation);}
